import { readFileSync } from "node:fs";

// The same fields as: gh pr list --repo RhinoHealth/fcp --author app/rhino-ai-agents --state all
//   --search "created:>=2026-11-23" --json number,title,state,body,latestReviews
const prs = JSON.parse(readFileSync("prs.json", "utf8"));

const requesterOf = (body) => body.match(/^Requested-by: @([\w-]+)$/m)?.[1] ?? "?";
const approversOf = (pr) => pr.latestReviews.filter((r) => r.state === "APPROVED").map((r) => r.author.login);
const hasFullProof = (body) => body.includes("### How it was checked") && body.includes("Trace: ") && /^Found \d/m.test(body);

console.log("| PR | State | Requester | Approver | Requester approved? | Full proof? |");
console.log("|---|---|---|---|---|---|");
for (const pr of prs) {
  const requester = requesterOf(pr.body);
  const approvers = approversOf(pr);
  const flag = approvers.includes(requester) ? "YES, a person must look" : "no";
  console.log(`| #${pr.number} | ${pr.state} | ${requester} | ${approvers.join(", ") || "-"} | ${flag} | ${hasFullProof(pr.body) ? "yes" : "no"} |`);
}

const merged = prs.filter((pr) => pr.state === "MERGED").length;
const finished = prs.filter((pr) => pr.state !== "OPEN").length;
const requesterApproved = prs.filter((pr) => approversOf(pr).includes(requesterOf(pr.body))).length;
console.log(`\nmerged ${merged} · ${Math.round((100 * merged) / finished)}% of the ${finished} finished PRs · requester approved ${requesterApproved} (must be 0)`);
